        capabilities: [
            { title: {"en": "Bridges, Flyovers & Underpasses Execution", "ar": "إنشاء الجسور والتقاطعات العلوية والأنفاق"}, desc: {"en": "Constructing bored-pile bridge foundations, piers, precast pre-stressed girders, and post-tensioned box girder decks with elastomeric bearings and expansion joints.", "ar": "تنفيذ أساسات الجسور والركائز والهامات، وتركيب الكمرات مسبقة الصب والإجهاد أو الجسور الصندوقية اللاحقة الإجهاد مع المساند المطاطية وفواصل التمدد."} },
            { title: {"en": "Stormwater Box Culverts & Wadi Protection", "ar": "عبارات تصريف السيول الصندوقية وحماية الأودية"}, desc: {"en": "Executing multi-cell reinforced concrete box culverts, open lined channels, riprap slope protection, and flood retention dams across wadi corridors.", "ar": "تنفيذ العبارات الخرسانية الصندوقية متعددة الفتحات، القنوات المبطنة، وتكسيات الحماية الحجرية (Riprap) لتصريف السيول وحماية الطرق والمخططات."} },
            { title: {"en": "Strategic Concrete Water Reservoirs & Tanks", "ar": "خزانات المياه الخرسانية الأرضية والعلوية"}, desc: {"en": "Building watertight underground and elevated concrete storage tanks using micro-silica concrete, PVC waterstops, and internal food-grade epoxy linings.", "ar": "تشييد الخزانات الخرسانية الضخمة بخرسانة منخفضة النفاذية مع فواصل التمدد المانعة للتسرب (Waterstops) والعزل الإيبوكسي المعتمد لمياه الشرب."} },
            { title: {"en": "Highways & Polymer-Modified Asphalt Paving", "ar": "إنشاء الطرق والسفلتة المعدلة بالبوليمر (Superpave)"}, desc: {"en": "Executing sub-base grading, aggregate base courses, and Superpave polymer-modified asphalt paving engineered to prevent rutting under Saudi heat and heavy loads.", "ar": "تنفيذ طبقات الردم والأساس الحصوي وفرش الخلطات الأسفلتية المعدلة بالبوليمر المقاومة للتخدد والتشقق تحت درجات الحرارة العالية وأحمال الشاحنات."} },
            { title: {"en": "Retaining Walls & MSE Earth Structures", "ar": "الجدران الاستنادية والتربة المسلحة (MSE Walls)"}, desc: {"en": "Constructing cantilever/counterfort concrete retaining walls, gabion walls, and Mechanically Stabilized Earth (MSE) walls for highway ramps and sloped terrains.", "ar": "بناء الجدران الاستنادية الخرسانية (الكابولية وذات الأعصاب)، جدران الجابيون، وجدران التربة المسلحة بالشبكات الجيوسنثتيكية لمداخل الجسور والمنحدرات."} },
            { title: {"en": "Soil Stabilization & Heavy Machine Foundations", "ar": "معالجة التربة الضعيفة وقواعد المعدات الصناعية"}, desc: {"en": "Treating sabkha and expansive soils with geogrids and engineered replacement, and casting vibration-isolated mass concrete foundations for turbines and plants.", "ar": "معالجة التربة السبخية والانتفاخية بالإحلال والتسليح الجيوتقني، وصب القواعد الخرسانية المسلحة المعزولة اهتزازياً للمصانع والتوربينات والمعدات الثقيلة."} }
        ],
