        capabilities: [
            { title: {"en": "Design & Build (EPC) & Authority Approvals", "ar": "عقود التصميم والتنفيذ (Design & Build) واعتمادات الجهات"}, desc: {"en": "Single-point responsibility for architectural, structural, and MEP design compliant with Balady, Civil Defense (SBC 801), SEC, NWC, and Salmani architectural codes.", "ar": "تولي المسؤولية الكاملة عن التصميم والتنفيذ واستخراج التراخيص والاعتمادات وفق اشتراطات منصة بلدي، الدفاع المدني (SBC 801)، والعمارة السلمانية والهويات المحلية."} },
            { title: {"en": "Value Engineering (VE) & Structural Optimization", "ar": "دراسات هندسة القيمة (Value Engineering) وتخفيض التكلفة"}, desc: {"en": "Re-engineering over-designed foundations, slabs, steel tonnage, and MEP systems to save 15–25% of construction cost while enhancing structural performance.", "ar": "مراجعة وإعادة هندسة الأساسات، سماكات البلاطات، أوزان الحديد، والأنظمة الكهروميكانيكية لتوفير 15% إلى 25% من ميزانية المشروع مع الحفاظ على أعلى معايير الجودة."} },
            { title: {"en": "3D BIM Coordination & Zero-Clash Shop Drawings", "ar": "تنسيق نمذجة (BIM LOD 400) وإصدار المخططات التنفيذية"}, desc: {"en": "Producing coordinated Revit/Navisworks models and detailed shop drawings (concrete, rebar BBS, MEP composite layouts) that eliminate site rework.", "ar": "بناء نماذج رقمية موحدة وكشف كافة التعارضات بين الإنشائي والمعماري والكهروميكانيك مسبقاً، وإصدار مخططات الورشة (Shop Drawings & BBS) جاهزة للتنفيذ الفوري."} },
            { title: {"en": "Structural Engineering for Towers & Long Spans", "ar": "الهندسة الإنشائية المتقدمة للأبراج والبحور الواسعة"}, desc: {"en": "Designing seismic and wind-resistant high-rise cores, post-tensioned floors, transfer slabs, and heavy industrial steel structures per SBC 301 & SBC 304.", "ar": "تصميم الأنظمة المقاومة للرياح والزلازل، بلاطات التحويل (Transfer Slabs)، الأسقف اللاحقة الإجهاد، والمنشآت المعدنية ذات البحور الكبيرة وفق كود SBC 301 وSBC 304."} },
            { title: {"en": "Saudi-Climate MEP & Energy Efficiency Design", "ar": "تصميم أنظمة الـ MEP وكفاءة الطاقة لمناخ المملكة"}, desc: {"en": "Engineering HVAC, electrical, and fire systems for 50°C ambient peaks while meeting Saudi Energy Conservation Code (SBC 601) thermal envelope standards.", "ar": "تصميم منظومات التكييف والكهرباء والحريق لتعمل بكفاءة قصوى في أجواء الصيف القياسية بالمملكة، مع تحقيق اشتراطات كود ترشيد الطاقة السعودي (SBC 601)."} },
            { title: {"en": "BOQ, Material Specs & LOD 500 As-Built Digital Twins", "ar": "حصر الكميات الدقيقة وإصدار مخططات (As-Built LOD 500)"}, desc: {"en": "Delivering accurate 5D BIM quantity take-offs, vendor-neutral technical specifications, and final LOD 500 As-Built models for seamless facility management.", "ar": "استخراج جداول الكميات الدقيقة (5D BIM BOQ) والمواصفات الفنية للمواد، وتسليم نموذج رقمي متكامل لما تم تنفيذه فعلياً (As-Built) لخدمة التشغيل والصيانة."} }
        ],
