        capabilities: [
            { title: {"en": "Central HVAC: Chillers, VRF/VRV & Smoke Management", "ar": "أنظمة التكييف المركزي (Chillers & VRF) وسحب الدخان"}, desc: {"en": "Supplying and installing T3-rated chillers, AHUs, VRF systems, GI/pre-insulated ductwork, and Civil Defense-approved smoke extraction fans per SBC 501.", "ar": "توريد وتركيب أنظمة التشيلرات، وحدات مناولة الهواء، أنظمة الـ VRF الموفرة للطاقة، ومراوح سحب الدخان وتضغيط السلالم المعتمدة من الدفاع المدني وفق كود SBC 501."} },
            { title: {"en": "MV/LV Electrical Power, Generators, Busbars & SEC", "ar": "القوى الكهربائية، المولدات، الـ Busbars، واعتمادات SEC"}, desc: {"en": "Installing transformers, LV switchgear, copper busbar risers, standby diesel generators, ATS/UPS systems, and completing SEC meter energization.", "ar": "تركيب المحولات، لوحات الجهد المنخفض، مجاري القضبان النحاسية (Busduct)، المولدات الاحتياطية وأنظمة الـ UPS، وإنجاز إجراءات إطلاق التيار مع شركة الكهرباء."} },
            { title: {"en": "Civil Defense Firefighting (UL/FM, FM-200 & Sprinklers)", "ar": "أنظمة مكافحة وإنذار الحريق المعتمدة من الدفاع المدني"}, desc: {"en": "Executing UL/FM fire pump sets, wet/dry sprinkler networks, foam systems, FM-200/Novec clean agent gas suppression, and addressable fire alarm panels.", "ar": "تنفيذ مضخات الحريق المعتمدة (UL/FM)، شبكات الرش الآلي والصناديق، الإطفاء بالغاز النظيف (FM-200 / Novec) لغرف السيرفرات، وأنظمة الإنذار المعنونة حتى إصدار ترخيص سلامة."} },
            { title: {"en": "Plumbing, Acoustic Drainage & Central Solar Water", "ar": "أعمال السباكة، الصرف الصامت، والتسخين المركزي"}, desc: {"en": "Installing PPR/PEX/Copper water supply, multi-layer acoustic drainage pipes, booster/transfer pump sets, grease traps, and central water filtration.", "ar": "تمديد شبكات التغذية الحرارية، أنظمة الصرف الصحي الصامت متعدد الطبقات، مضخات الرفع والتعزيز (Booster Pumps)، والسخانات المركزية وفلاتر المعالجة."} },
            { title: {"en": "Smart Building Automation (BMS) & Low Current (ELV)", "ar": "أتمتة المباني الذكية (BMS) وأنظمة التيار الخفيف (ELV)"}, desc: {"en": "Integrating BMS controllers to monitor HVAC/power efficiency alongside IP CCTV, access control, public address, audiovisual, and fiber-optic data networks.", "ar": "ربط وبرمجة نظام إدارة المبنى الذكي (BMS) للتحكم بالتكييف والإنارة وتوفير الطاقة، مع تنفيذ شبكات الكاميرات، التحكم بالدخول، الصوتيات، والألياف الضوئية."} },
            { title: {"en": "Composite BIM Coordination & Certified TAB Testing", "ar": "التنسيق المجمع (Composite BIM) واختبارات الموازنة (TAB)"}, desc: {"en": "Eliminating ceiling clashes via composite shop drawings and performing certified Testing, Adjusting & Balancing (TAB) for optimal airflow and acoustics.", "ar": "إنهاء تعارضات الأسقف عبر مخططات الـ Composite قبل التنفيذ، وإجراء اختبارات الفحص والموازنة الهوائية والمائية (TAB) لضمان هدوء وكفاءة التبريد في كل غرفة."} }
        ],
